import json, time
from http.server import BaseHTTPRequestHandler, HTTPServer

def today_ms(hour):
    import datetime
    now = datetime.datetime.now(datetime.timezone.utc)
    dt = now.replace(hour=hour, minute=0, second=0, microsecond=0)
    return int(dt.timestamp() * 1000)

BOOKABLES = [
    {"id": "b1", "title": "Room-A", "imgUrl": None},
    {"id": "b2", "title": "Room-B", "imgUrl": None},
]

BOOKINGS = [
    {"id": "bk1", "bookableItems": [{"bookableId": "b1"}], "timeBegin": today_ms(9), "timeEnd": today_ms(10)},
    {"id": "bk2", "bookableItems": [{"bookableId": "b1"}], "timeBegin": today_ms(14), "timeEnd": today_ms(15)},
    {"id": "bk3", "bookableItems": [{"bookableId": "b2"}], "timeBegin": today_ms(11), "timeEnd": today_ms(12)},
]

class H(BaseHTTPRequestHandler):
    def _send(self, code, obj):
        b = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)
    def log_message(self, *a):
        pass
    def do_POST(self):
        n = int(self.headers.get("Content-Length", 0))
        self.rfile.read(n)
        if self.path.endswith("/auth/signin"):
            self._send(200, {"accessToken": "tok", "refreshToken": "ref"})
        elif self.path.endswith("/auth/refresh"):
            self._send(200, {"accessToken": "tok2", "refreshToken": "ref2"})
        else:
            self._send(404, {})
    def do_GET(self):
        if self.path.endswith("/bookables"):
            self._send(200, BOOKABLES)
        elif self.path.endswith("/bookings"):
            self._send(200, BOOKINGS)
        else:
            self._send(404, {})

HTTPServer(("0.0.0.0", 8002), H).serve_forever()
